import React, { useMemo, useState, useEffect, useCallback } from 'react';
import { GroupedHistoryItem, Message, QuestionResponse, HistoryDataPoint } from './types';
import {
  askQuestion,
  getCategories,
  getUserProgress,
  clearUserHistory,
  CategoryInfo,
  getErrorMessage,
  getAlerts,
  getGroupedHistory,
  getUserServiceMetrics,
  fetchCurrentUser,
  setAuthToken,
  AuthUserPublic
} from './api';
import { Sidebar } from './components/Sidebar';
import { ChatContainer } from './components/ChatContainer';
import { TrendChart } from './components/TrendChart';
import { ReportPanel } from './components/ReportPanel';
import { UserProfile, UserSelector } from './components/UserSelector';
import { LoginPanel } from './components/LoginPanel';
import { profilesStorageKey } from './userStorage';
import './App.css';

const DEMO_QUESTIONS = [
  '最近学习压力很大，学不进去怎么办？',
  '我感觉很孤独，没有朋友',
  '和室友关系不好，很烦恼',
  '担心未来找不到工作',
  '总是情绪低落，提不起劲'
];
const DEFAULT_USERS: UserProfile[] = [
  { id: 'user1', name: '小明', avatar: '👦' },
  { id: 'user2', name: '小红', avatar: '👧' },
  { id: 'user3', name: '小李', avatar: '👨' }
];
const CARE_PLAN_STORAGE_KEY = 'psyqa_care_plans';

const profilesToRecord = (list: UserProfile[]): Record<string, UserProfile> =>
  list.reduce<Record<string, UserProfile>>((acc, user) => {
    acc[user.id] = user;
    return acc;
  }, {});

const createWelcomeMessage = (): Message => ({
  id: '1',
  type: 'bot',
  content: '您好！欢迎来到心理港湾。请问您有什么困扰或问题想要倾诉吗？',
  timestamp: new Date().toLocaleString('zh-CN')
});

const emotionToMetrics = (emotion: QuestionResponse['emotion']['emotion']) => {
  const profile: Record<typeof emotion, { stress: number; anxiety: number; stability: number }> = {
    happy: { stress: 28, anxiety: 25, stability: 86 },
    sad: { stress: 65, anxiety: 58, stability: 45 },
    anxious: { stress: 78, anxiety: 80, stability: 38 },
    angry: { stress: 72, anxiety: 56, stability: 42 },
    lonely: { stress: 60, anxiety: 53, stability: 48 },
    neutral: { stress: 45, anxiety: 40, stability: 65 },
    hopeful: { stress: 32, anxiety: 30, stability: 82 },
    confused: { stress: 58, anxiety: 55, stability: 50 },
    frustrated: { stress: 68, anxiety: 60, stability: 44 },
    guilty: { stress: 57, anxiety: 54, stability: 47 },
    shameful: { stress: 62, anxiety: 58, stability: 43 },
    proud: { stress: 30, anxiety: 28, stability: 84 }
  };

  return profile[emotion] || profile.neutral;
};

function App() {
  const [messages, setMessages] = useState<Message[]>([
    createWelcomeMessage()
  ]);
  const [categories, setCategories] = useState<CategoryInfo[]>([]);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [userProfiles, setUserProfiles] = useState<Record<string, UserProfile>>({});
  const [checkingAuth, setCheckingAuth] = useState(true);
  const [enteredApp, setEnteredApp] = useState(false);
  const [guestMode, setGuestMode] = useState(false);
  const [sessionUser, setSessionUser] = useState<AuthUserPublic | null>(null);
  const [trendData, setTrendData] = useState<HistoryDataPoint[]>([]);
  const [latestReport, setLatestReport] = useState<{
    emotion: QuestionResponse['emotion'];
    risk: QuestionResponse['risk'];
    emotionStyle: QuestionResponse['emotionStyle'];
    report: string;
  } | null>(null);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [showDemoPanel, setShowDemoPanel] = useState(true);
  const [showOpsPanel, setShowOpsPanel] = useState(false);
  const [groupedHistory, setGroupedHistory] = useState<Record<string, GroupedHistoryItem[]>>({});
  const [serviceMetrics, setServiceMetrics] = useState<{ thresholdMs: number; users: Array<{ userId: string; avgResponseTimeMs: number; slowRequests: number; failedRequests: number; totalRequests: number }> } | null>(null);
  const [alerts, setAlerts] = useState<Array<{ level: 'high' | 'medium'; message: string; userId: string; time: string }>>([]);
  const [carePlans, setCarePlans] = useState<Record<string, string>>(() => {
    try {
      const raw = localStorage.getItem(CARE_PLAN_STORAGE_KEY);
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  });
  const [carePlanInput, setCarePlanInput] = useState('');

  useEffect(() => {
    const fetchCategories = async () => {
      const maxAttempts = 5;
      for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
          const cats = await getCategories();
          setCategories(cats);
          return;
        } catch (error) {
          if (attempt === maxAttempts) {
            console.error('Failed to fetch categories:', error);
            setMessages((prev) => [
              ...prev,
              {
                id: `sys-${Date.now()}`,
                type: 'bot',
                content: `分类加载失败：${getErrorMessage(error)}`,
                timestamp: new Date().toLocaleString('zh-CN')
              }
            ]);
            return;
          }
          await new Promise((resolve) => setTimeout(resolve, attempt * 600));
        }
      }
    };
    fetchCategories();
  }, []);

  useEffect(() => {
    const fetchProgress = async () => {
      try {
        const progress = await getUserProgress(currentUserId);
        const grouped = await getGroupedHistory(currentUserId);
        const data: HistoryDataPoint[] = progress.history.map((h, index) => ({
          date: `第${index + 1}次`,
          // Use deterministic synthetic baseline instead of random values.
          stressLevel: 45 + (index % 4) * 5,
          anxietyLevel: 38 + (index % 5) * 4,
          moodStability: 62 - (index % 3) * 3
        }));
        setTrendData(data);
        setGroupedHistory(grouped.groups || {});
      } catch (error) {
        console.error('Failed to fetch progress:', error);
      }
    };
    fetchProgress();
  }, [currentUserId]);

  useEffect(() => {
    setCarePlanInput(carePlans[currentUserId] || '');
  }, [carePlans, currentUserId]);

  useEffect(() => {
    if (!showOpsPanel) {
      return;
    }
    const fetchOpsData = async () => {
      try {
        const [metrics, alertData] = await Promise.all([getUserServiceMetrics(), getAlerts()]);
        setServiceMetrics({ thresholdMs: metrics.thresholdMs, users: metrics.users });
        setAlerts(alertData.alerts);
      } catch (error) {
        console.error('Failed to fetch ops data:', error);
      }
    };
    fetchOpsData();
  }, [showOpsPanel, messages.length]);

  const handleSend = async (question: string, description: string) => {
    setMessages((prev) => [
      ...prev,
      { id: Date.now().toString(), type: 'user', content: question, timestamp: new Date().toLocaleString('zh-CN') }
    ]);

    setIsLoading(true);

    try {
      const careContext = carePlans[currentUserId]?.trim();
      const enhancedDescription = [description, careContext ? `【用户关怀计划】${careContext}` : '']
        .filter(Boolean)
        .join('\n');
      const response: QuestionResponse = await askQuestion(question, enhancedDescription, currentUserId);

      setLatestReport({
        emotion: response.emotion,
        risk: response.risk,
        emotionStyle: response.emotionStyle,
        report: response.report
      });

      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          type: 'bot',
          content: response.answer,
          knowledgeSources: response.knowledgeSources,
          similarQuestions: response.similarQuestions,
          emotion: response.emotion,
          risk: response.risk,
          emotionStyle: response.emotionStyle,
          report: response.report,
          timestamp: new Date().toLocaleString('zh-CN')
        }
      ]);

      const metrics = emotionToMetrics(response.emotion.emotion);
      setTrendData((prev) => [
        ...prev,
        {
          date: `第${prev.length + 1}次`,
          stressLevel: metrics.stress,
          anxietyLevel: metrics.anxiety,
          moodStability: metrics.stability
        }
      ]);

      if (response.risk.level === 'high' || response.risk.level === 'critical') {
        setMessages((prev) => [
          ...prev,
          {
            id: `followup-${Date.now()}`,
            type: 'bot',
            content: '我想继续确认你的状态：你现在身边有可以立即联系的人吗？如果愿意，我可以帮你做一个3步安全行动清单。',
            timestamp: new Date().toLocaleString('zh-CN')
          }
        ]);
      }
    } catch (error) {
      console.error('Error sending question:', error);
      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          type: 'bot',
          content: `抱歉，我暂时无法回答您的问题：${getErrorMessage(error)}`,
          timestamp: new Date().toLocaleString('zh-CN')
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSimilarQuestionClick = (question: string) => {
    handleSend(question, '');
  };

  const handleUserChange = (userId: string) => {
    setCurrentUserId(userId);
    setMessages([createWelcomeMessage()]);
    setLatestReport(null);
  };

  const handleNewUser = (user: UserProfile) => {
    setUserProfiles((prev) => ({
      ...prev,
      [user.id]: user
    }));
    setCurrentUserId(user.id);
    setMessages([createWelcomeMessage()]);
    setLatestReport(null);
  };

  const handleClearHistory = async () => {
    try {
      await clearUserHistory(currentUserId);
      setMessages([createWelcomeMessage()]);
      setTrendData([]);
      setLatestReport(null);
    } catch (error) {
      console.error('Failed to clear history:', error);
      setMessages((prev) => [
        ...prev,
        {
          id: `clear-${Date.now()}`,
          type: 'bot',
          content: `清空历史失败：${getErrorMessage(error)}`,
          timestamp: new Date().toLocaleString('zh-CN')
        }
      ]);
    }
  };

  const handleExportHistory = () => {
    const mode = window.prompt('请选择导出格式：txt / json / report', 'txt')?.toLowerCase();
    const historyText = messages.map((m) => {
      return `${m.type === 'user' ? '用户' : '助手'} [${m.timestamp}]:\n${m.content}\n`;
    }).join('\n---\n\n');
    const groupedDigest = Object.entries(groupedHistory)
      .map(([group, items]) => `【${group}】${items.length}条`)
      .join('\n');
    const reportText = [
      `用户：${currentUserLabel}`,
      `导出时间：${new Date().toLocaleString('zh-CN')}`,
      `会话分组：\n${groupedDigest || '暂无'}`,
      `\n对话记录：\n${historyText}`
    ].join('\n\n');

    let content = historyText;
    let fileType = 'text/plain;charset=utf-8';
    let ext = 'txt';
    if (mode === 'json') {
      content = JSON.stringify({ userId: currentUserId, groupedHistory, messages }, null, 2);
      fileType = 'application/json;charset=utf-8';
      ext = 'json';
    } else if (mode === 'report') {
      content = reportText;
    }

    const blob = new Blob([content], { type: fileType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `对话记录_${new Date().toLocaleDateString('zh-CN').replace(/\//g, '-')}.${ext}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    if (mode === 'report') {
      const printWindow = window.open('', '_blank');
      if (printWindow) {
        printWindow.document.write(`<pre>${reportText.replace(/</g, '&lt;')}</pre>`);
        printWindow.document.close();
        printWindow.focus();
        printWindow.print();
      }
    }
  };

  const handleDemoQuestion = (question: string) => {
    handleSend(question, '');
  };

  const toggleDemoMode = () => {
    setIsDemoMode(!isDemoMode);
    if (!isDemoMode) {
      setShowDemoPanel(true);
    }
  };
  const saveCarePlan = () => {
    const next = { ...carePlans, [currentUserId]: carePlanInput.trim() };
    setCarePlans(next);
    localStorage.setItem(CARE_PLAN_STORAGE_KEY, JSON.stringify(next));
  };

  const topSlowUsers = useMemo(
    () => (serviceMetrics?.users || []).slice(0, 5),
    [serviceMetrics]
  );
  const currentUser = userProfiles[currentUserId];
  const currentUserLabel = currentUser ? `${currentUser.name} ${currentUser.avatar}` : currentUserId;

  return (
    <div className="app-container">
      <header className="header">
        <div className="header-left">
          <h1>🏠 心理港湾</h1>
          <p>温暖的心灵栖息地，陪伴您走过每一段旅程</p>
        </div>
        <div className="header-right">
          <div className="current-user">
            当前用户: {currentUserLabel}
          </div>
          <button 
            className={`demo-toggle ${isDemoMode ? 'active' : ''}`}
            onClick={toggleDemoMode}
          >
            🎬 {isDemoMode ? '退出演示' : '演示模式'}
          </button>
          <button
            className={`demo-toggle ${showOpsPanel ? 'active' : ''}`}
            onClick={() => setShowOpsPanel((prev) => !prev)}
          >
            🛎️ {showOpsPanel ? '关闭告警中心' : '打开告警中心'}
          </button>
        </div>
      </header>

      <main className="main-content">
        <aside className="sidebar-panel">
          <UserSelector
            currentUserId={currentUserId}
            onUserChange={handleUserChange}
            onNewUser={handleNewUser}
          />
          <Sidebar
            categories={categories}
            activeCategory={activeCategory}
            onCategorySelect={setActiveCategory}
          />
          <div className="care-plan-card">
            <h3>🧩 个性化关怀计划</h3>
            <textarea
              value={carePlanInput}
              onChange={(e) => setCarePlanInput(e.target.value)}
              placeholder="例如：考试季容易焦虑，建议优先给出短步骤安抚建议"
            />
            <button className="save-care-btn" onClick={saveCarePlan}>保存计划</button>
          </div>
        </aside>

        <div className="main-panel">
          <div className="top-section">
            <div className="chart-section">
              <TrendChart data={trendData} />
            </div>
            {latestReport && (
              <div className="report-section">
                <ReportPanel
                  emotion={latestReport.emotion}
                  risk={latestReport.risk}
                  emotionStyle={latestReport.emotionStyle}
                  report={latestReport.report}
                />
              </div>
            )}
          </div>
          {isDemoMode && showDemoPanel && (
            <div className="demo-panel">
              <div className="demo-header">
                <h3>🎯 快捷体验</h3>
                <button className="demo-close" onClick={() => setShowDemoPanel(false)}>✕</button>
              </div>
              <div className="demo-questions">
                {DEMO_QUESTIONS.map((question, index) => (
                  <button
                    key={index}
                    className="demo-question-btn"
                    onClick={() => handleDemoQuestion(question)}
                  >
                    💡 {question}
                  </button>
                ))}
              </div>
            </div>
          )}
          {showOpsPanel && (
            <div className="ops-panel">
              <div className="ops-col">
                <h3>🚨 管理员告警中心</h3>
                {alerts.length === 0 && <p className="muted">暂无告警</p>}
                {alerts.map((a, idx) => (
                  <div key={`${a.userId}-${idx}`} className={`alert-item ${a.level}`}>
                    <div>{a.message}</div>
                    <small>{a.time}</small>
                  </div>
                ))}
              </div>
              <div className="ops-col">
                <h3>📈 用户服务质量面板</h3>
                <p className="muted">慢请求阈值：{serviceMetrics?.thresholdMs ?? '-'}ms</p>
                {topSlowUsers.map((u) => (
                  <div key={u.userId} className="metric-item">
                    <strong>{u.userId}</strong>
                    <span>平均耗时 {u.avgResponseTimeMs}ms</span>
                    <span>慢请求 {u.slowRequests}</span>
                    <span>失败 {u.failedRequests}</span>
                    <span>总量 {u.totalRequests}</span>
                  </div>
                ))}
              </div>
              <div className="ops-col">
                <h3>🗂️ 会话标签与分组</h3>
                {Object.keys(groupedHistory).length === 0 && <p className="muted">暂无会话分组</p>}
                {Object.entries(groupedHistory).map(([group, items]) => (
                  <div key={group} className="group-item">
                    <div className="group-title">{group} ({items.length})</div>
                    <div className="group-tags">
                      {Array.from(new Set(items.flatMap((item) => item.tags))).slice(0, 8).map((tag) => (
                        <span key={tag} className="group-tag">{tag}</span>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
          <div className="chat-section">
            <ChatContainer
              messages={messages}
              isLoading={isLoading}
              onSend={handleSend}
              onSimilarQuestionClick={handleSimilarQuestionClick}
              onClearHistory={handleClearHistory}
              onExportHistory={handleExportHistory}
            />
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;
